INSERT INTO public.products
  (brand_id, title, description, image_url, affiliate_link, price, currency, category, gender, body_shapes, seasonal_palettes, in_stock, verification_status, last_verified_at, rating)
VALUES
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Loopwheel Cotton Long Sleeve T-Shirt', 'A men''s crewneck long sleeve t-shirt made of smooth organic cotton jersey and features an extremely soft and airy texture.', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4550723644693_org_7d7f1cab-8e99-4213-a5ba-a6c9ae151115.jpg?v=1789675388', 'https://www.muji.us/products/loopwheel-cotton-long-sleeve-t-shirt-ab1r926a', 60, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Women''s Soy Fiber Blend Ribbed Crewneck T-Shirt', 'Made from lightweight knitted soy pulp for a soft texture, making it gentle and comfortable to wear. The fine rib design adds an delicate touch that can also be worn casually.', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4550584045851_org_53ca69ad-5f0a-468d-a6bf-0993df199399.jpg?v=1762631973', 'https://www.muji.us/products/womens-soy-fiber-blend-ribbed-crew-neck-long-sleeve-t-shirt-bb2qm24a', 19.99, 'USD', 'Tops', 'Female', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'Thermal Henley in Cozy Waffle | Heathered Charcoal', 'Not your basic waffle. This henley’s built tough with a textured face and a smooth jersey interior that’s soft but ready for whatever you throw at it.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/c24606a4_d49e.jpg?v=1756349181', 'https://www.everlane.com/products/mens-thermal-cozy-waffle-henley-heathered-charcoal', 88, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Fairway Fresh Men''s Crew-Neck Golf Top', 'Celebrating 40 years of Nike Golf, this smooth and structured sweater showcases the flair Seve Ballesteros brought to the game with an allover print pulled from our first golf poster.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/12434db8-13aa-4017-a6e6-0f68cdc08676/M+NK+FF+CREW+SEVE.png', 'https://www.nike.com/t/fairway-fresh-mens-crew-neck-golf-top-ClchJ47S/IO1964-100', 94.97, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Brushed High Neck T-Shirt', 'A men''s long-sleeved high neck t-shirt made with brushed cotton jersey fabric for warmth and a soft feel. Perfect to keep you warm in fall and winter.', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4547315468027_org.jpg?v=1757350571', 'https://www.muji.us/products/brushed-high-neck-t-shirt-ab1mu25a', 19.99, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Sportswear Premium Essentials T-Shirt', 'Dial up a classic. Heavyweight cotton gives this premium, roomy tee a slightly textured feel and structured look for durable, daily comfort.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/cafd6a16-0b8c-4799-ba36-0f39e7b6701e/U+NSW+TEE+LSE+PREM+ORANGE.png', 'https://www.nike.com/t/sportswear-premium-essentials-t-shirt-hAgVIb9d/IH1351-006', 34.97, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike N.A.C. Men''s Dri-FIT Oversized Fleece Training Hoodie', 'The N.A.C. is where strength meets style—built for performance, designed for gym life. This hoodie has a spacious fit inspired by throwback pump covers and soft, sweat-wicking fleece to help keep you dry through every rep.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/11d581d2-9b13-4142-adae-c42b9be07693/M+NK+DF+NAC+FLC+PUMP+COVER+HDY.png', 'https://www.nike.com/t/nac-mens-dri-fit-oversized-fleece-training-hoodie-t7mydNNM/IM3609-377', 64.97, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Cotton Jersey Wide T-Shirt', 'This classic men''s crewneck short sleeve t-shirt is designed with durability and comfort in mind, featuring a comfortable neckline and made with pre-washed organic cotton jersey for a soft touch.', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4550723085090_org.jpg?v=1776358299', 'https://www.muji.us/products/cotton-jersey-wide-t-shirt-ab1qx26s', 19.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Uniqlo'), 'MANGA UT SHUEISHA 100th UT Graphic T-Shirt | YU-GI-OH!', 'The front features Yami Yugi and his monsters, while the back features Yugi and his monsters.\u003cbr>\u003cbr>MANGA UT SHUEISHA 100th\u003cbr>\u003cbr>From timeless legends to the latest releases, numerous masterpiece manga titles from', 'https://image.uniqlo.com/UQ/ST3/us/imagesgoods/489655/item/usgoods_00_489655_3x4.jpg', 'https://www.uniqlo.com/us/en/products/E489655-000/00', 29.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), 5),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike SB Men''s Dri-FIT Bowler Skate Top', 'This retro-inspired bowler top is made with Dri-FIT tech to help you stay dry and comfortable. The boxy, oversized fit makes for easy movement. Air Max 90, Hypervenom and Nike soccer graphics mix to create a mashup of sport and culture.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/4b7836c4-8cbc-453f-a0de-502470babbc6/M+NK+SB+DF+BOWLER+FR+SU26.png', 'https://www.nike.com/t/sb-mens-dri-fit-bowler-skate-top-XRCl0sn3/IR8701-012', 51.97, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Jordan Flight Club Men''s Jersey', 'Smooth, lightweight and with just a little sheen—this loose-fitting jersey top brings it. Jordan branding lets ''em know who you rep.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/d29cbdec-3bc0-4539-ad9d-b6a06d89af6d/M+J+FLT+CLB+JERSEY.png', 'https://www.nike.com/t/jordan-flight-club-mens-jersey-0WUotqYq/IF1898-010', 87.97, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Track Hoodie | Black', 'Featuring a hood, raglan sleeves, a front kangaroo pocket, and a relaxed fit, the Track Hoodie has a signature look that will stand the test of time.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/cd38afec_7328.jpg?v=1750093695', 'https://www.everlane.com/products/mens-track-hoodie-black', 31, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Uniqlo'), 'AIRism Cotton Oversized Striped T-Shirt', 'Shop stylish and comfortable clothes for women, men, kids and babies from UNIQLO. Enjoy $10 off your first order of $75 or more.', 'https://image.uniqlo.com/UQ/ST3/us/imagesgoods/484508/item/usgoods_69_484508_3x4.jpg', 'https://www.uniqlo.com/us/en/products/E484508-000/00', 14.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), 4.8),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Long-Sleeve Summer Shirt | Slate', 'The Long-Sleeve Summer Shirt is built to stay cool, thanks to its lightweight construction and double-gauze material. Plus, it’s made of 100% organic cotton for superior breathability and undeniable softness.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/ef728262_7341.jpg?v=1750093772', 'https://www.everlane.com/products/mens-long-sleeve-summer-shirt-slate', 30, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike ACG "Solar Chase" Men''s Dri-FIT UV Protection Hooded Trail Running Top', 'Sunny days and sweaty runs—that''s what this top is built for. It''s lightweight, sweat-wicking and has UV protection. Elastic binding on the hood gives you a snug fit and thumbholes help keep the sleeves in place.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/2dc884c1-cc0d-4552-aabf-3687e48ef523/M+ACG+DF+UV+SLR+CHS+LS+HD+AOP.png', 'https://www.nike.com/t/acg-solar-chase-mens-dri-fit-uv-protection-hooded-trail-running-top-bXjz0RDx/IQ7684-307', 67.97, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Men''s Jersey Crew Neck Long Sleeve T-Shirt', 'Classic long sleeve t-shirt that is soft on the skin and moderately thick. Item Size Chart Size Chest Width Shoulder Width Hem Width Sleeve Length Length Waist Width Neck to Sleeve XS 20.5" (52.0 cm) 18.1" (46.0 cm)', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4550584280962_org_b0ddd839-05a9-46fd-a5f7-0e50ea63547b.jpg?v=1762275089', 'https://www.muji.us/products/mens-jersey-crew-neck-long-sleeve-t-shirt-ab1l324a', 19.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Uniqlo'), 'Premium Linen Shirt', 'Shop stylish and comfortable clothes for women, men, kids and babies from UNIQLO. Enjoy $10 off your first order of $75 or more.', 'https://image.uniqlo.com/UQ/ST3/us/imagesgoods/455957/item/usgoods_30_455957_3x4.jpg', 'https://www.uniqlo.com/us/en/products/E455957-000/00', 49.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), 4.6),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Premium-Weight Crew | Uniform | Graphite', 'We made these tees to last, a durable knit with a dry feel and medium weight that will get softer over years of wear.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/8e3d0f01_847b.jpg?v=1753411631', 'https://www.everlane.com/products/mens-premium-weight-crew-graphite', 19, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'No-Sweat Textured Zip Polo | Heathered Olive Night', 'A lightweight update to the No-Sweat Sweater Polo you already love. Crafted with organic cotton and COOLMAX® EcoMade fiber, it’s breathable, soft, and textured with a half-zip closure.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2026-07-05_M-SWTR-NOS-TXT-POLO-ONH_M1.jpg?v=1783441716', 'https://www.everlane.com/products/mens-no-sweat-textured-zip-polo-heathered-olive-night', 83, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Classic Short-Sleeve Shirt in Linen | Light Blue', 'Linen is naturally breathable and has a texture that looks even better wrinkled. This short-sleeve linen button down shirt is a classic warm-weather choice for good reason.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/f2bc0a8c_541d.jpg?v=1753411850', 'https://www.everlane.com/products/mens-linen-ss-shirt-light-blue', 35, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Broadcloth Overshirt', 'Enjoy comfort from the first wear with this men''s washed broadcloth over shirt, wearable as a shirt or as a jacket. The fabric undergoes a special washing process to ensure a soft, worn-in feel from the start.', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4550723382151_org_a1657d88-ad28-48fb-bc82-673b02876a64.jpg?v=1787253380', 'https://www.muji.us/products/broadcloth-overshirt-ac24q26a', 49.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Cotton Slub Henley | Pelican', 'Made of 100% Good Earth Cotton®, The Cotton Slub Henley features a three-button placket at the center front and a relaxed fit in our newest slub-textured cotton—for that perfectly imperfect vintage feel.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/1af5b7bf_6883.jpg?v=1753411689', 'https://www.everlane.com/products/mens-good-earth-cotton-slub-henley-pelican', 23, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Kobe Men''s Dri-FIT Fleece Pullover Basketball Hoodie', 'Kobe’s single-mindedness came deep from within. He refused to settle for anything less than giving his absolute best every single day. And those moments where his dedication paid off? The emotion poured out in a joyful fury.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/930e98b6-9389-4d0e-ba1b-56304e1b60db/KB+M+NK+DF+FLC+PO+HDY+SSNL1.png', 'https://www.nike.com/t/kobe-mens-dri-fit-fleece-pullover-basketball-hoodie-xZIRWPKg/IQ0947-382', 62.97, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Uniqlo'), 'ONE PIECE UT Graphic T-Shirt', 'The Straw Hat Crew who escaped from the Future Island Egghead and arrived at Elbaph, the long-awaited Land of Giants.', 'https://image.uniqlo.com/UQ/ST3/us/imagesgoods/482770/item/usgoods_00_482770_3x4.jpg', 'https://www.uniqlo.com/us/en/products/E482770-000/00', 14.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), 5),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The ReNew Fleece-Lined Heavyweight Overshirt | Heather Charcoal', 'The Heavyweight Overshirt works great as a shirt, as an easy light jacket, or as a warm mid-layer under a coat. Plus, the 8 oz heavy cotton twill is durable and warm. Overshirt, over-sweater, under-jacket—your call.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/7a8925a2_71ab.jpg?v=1753411733', 'https://www.everlane.com/products/mens-fleece-lined-overshirt-heather-charcoal', 48, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'AFC Richmond Men''s Nike T-Shirt', 'Rep AFC Richmond with this Nike tee. Made with soft cotton and a relaxed fit, it can help keep you comfy while you''re on your way to greatness.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/99ba5962-d9d8-416d-bc22-9e7152783483/TED+LASSO+M+CORE+CTN+SST.png', 'https://www.nike.com/t/afc-richmond-mens-nike-t-shirt-gphfs3KO/M11332P043AFCR-RYL', 35, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Mad 90 Pack "Tiempo"', 'This long-sleeve jersey channels energy from the iconic 2005 Tiempo, a cleat that represented soccer through its most expressive era—when the game was played with shameless joy.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/2f097473-c320-4992-aefc-11480ef80a72/M+NSW+FAMLY+REUNN+LS+JSY.png', 'https://www.nike.com/t/mad-90-pack-tiempo-mens-long-sleeve-jersey-8fPetN6x/IU8345-010', 51.97, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Uniqlo'), 'Pokémon UT Graphic T-Shirt', 'Pokémon\u003cbr>\u003cbr>To celebrate 30 years of Pokémon, the second UT collection is set to launch.\u003cbr>\u003cbr>This collection features special designs of Pokémon and their protagonists rendered in monochrome, video game-style', 'https://image.uniqlo.com/UQ/ST3/us/imagesgoods/489909/item/usgoods_00_489909_3x4.jpg', 'https://www.uniqlo.com/us/en/products/E489909-000/00', 29.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), 5),
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Cotton Pique Polo Shirt', 'Versatile for a variety of occasions, this lightweight men''s washed polo shirt is ideal for everyday and smart casual wear. Made from smooth, cooling pique knit material for a refreshing feel on warm days.', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4550723052702_org.jpg?v=1773944116', 'https://www.muji.us/products/cotton-pique-polo-shirt-ab1ov26s', 29.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Organic Cotton Crew | Lily Pad', 'An iconic tee, with clean lines and a classic crew neck. The fabric is a midweight, durable organic cotton that gets softer over time.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/0acf5a00_f58a.jpg?v=1753411460', 'https://www.everlane.com/products/mens-organic-cotton-crew-tee-lily-pad', 15, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Flannel Stand Collar Shirt', 'A cozy men''s flannel shirt that you''ll want to wear all-day during the fall and winter months. The special brushing process of the fabric gives it a unique soft texture that will keep you warm and comfortable.', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4547315950256_org_f5bce5f0-6542-4d30-ab9c-09dda100e9cb.jpg?v=1759775535', 'https://www.muji.us/products/flannel-stand-collar-shirt-ac21125a', 59.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Premium-Weight Rugby Shirt | Seagrass / Canvas Tan', 'Featuring a flat rib-knit collar with button placket, long sleeves, ribbed cuffs, and a straight hem, the Premium-Weight Rugby Shirt is the perfect nod to a classic fit. Plus, it pairs well with our Performance Chino.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/e20df99a_7685.jpg?v=1753411585', 'https://www.everlane.com/products/mens-rugby-shirt-seagrass-canvas-tan', 36, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The No-Sweat Button-Down Polo | Heather Grey', 'This piece features a slim polo top in a textured sweater knit fabric, short sleeves, button-front placket, and made of a blend of 60% organic cotton, and 40% EcoMade Coolmax materials.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/b70ba0d4_839e.jpg?v=1753411868', 'https://www.everlane.com/products/mens-no-sweat-button-down-polo-hthr-grey', 30, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Muji'), 'Heavyweight Cotton T-Shirt', 'This long-sleeved crew neck t-shirt features a thick, densely knitted cotton fabric that provides durability and warmth during the colder months. Made with pre-washed organic cotton.', 'https://cdn.shopify.com/s/files/1/0556/8066/3742/files/4548076907633_org.jpg?v=1767214150', 'https://www.muji.us/products/cotton-heavyweight-t-shirt-ab1nu26s', 29.9, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Startup Short-Sleeve Shirt | Kalamata', 'This slim fit, short-sleeve, naturally stretchy shirt features a chest pocket with a handy hidden zipper pocket inside.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/730a23bc_6724.jpg?v=1753411843', 'https://www.everlane.com/products/mens-startup-ss-shirt-kalamata', 25, 'USD', 'Tops', 'Male', '{}', '{}', true, 'verified', now(), NULL),
