  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike ACG Ultrafly Trail Trail Racing Shoes', 'Ultralight foam and enhanced grip fuel your trail speed. The Ultrafly Trail takes what you love about the original and refines it, so you can go the distance.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/97be2dbb-41f1-4177-8c1d-6a075d9ccd5c/NIKE+ACG+ULTRAFLY+TRAIL.png', 'https://www.nike.com/t/acg-ultrafly-trail-trail-racing-shoes-uNHxL3GA/HF5668-300', 260, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'ACG LDV Men''s Shoes', 'Before ACG was ACG, the LDV summited peaks. Initially a long-distance running shoe, the LDV underwent some durability upgrades to get it trail ready.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/15ac5aab-5224-4405-bee3-a74991312925/NIKE+ACG+LDV.png', 'https://www.nike.com/t/acg-ldv-mens-shoes-P92RMxcR/IF2857-401', 130, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Free Run 5.0 Men''s Road Running Shoes', 'RUN FREE, STAY FLEXIBLE. Made from at least 20% recycled material by weight, the sock-like boot of this Nike Free is designed to transition from running to training to your everyday routine.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/bb9e1913-0ef6-4792-bf6c-57b6a57fc070/NIKE+FREE+RN+5.0+NEXT+NATURE.png', 'https://www.nike.com/t/free-run-5-mens-road-running-shoes-Xp40hf/CZ1884-006', 79.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 6 Retro "Black and White"', 'Start your little one''s own journey on the right foot with a shoe that pairs durability with style—and a throwback to MJ''s championship game shoe from ''91.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/e15ed44f-ad6b-451f-bbef-9b0b8b0d3aac/AIR+JORDAN+6+RETRO.png', 'https://www.nike.com/t/air-jordan-6-retro-black-and-white-mens-shoes-mVJLdEz6/CT8529-108', 215, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 13 Retro "Flint"', 'The Jordan 13 brings back the memorable shoe that MJ wore during the ''97-98 season, all the way to his 6th championship title.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/a4d51f6a-183e-4633-b090-a515255c4b04/AIR+JORDAN+13+RETRO.png', 'https://www.nike.com/t/air-jordan-13-retro-flint-mens-shoes-OpBQMdeV/IW3808-400', 215, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Tatum 4 Basketball Shoes', 'Just like Jayson’s game, his shoe is always evolving. Pushing innovation forward with each new shoe while keeping what works from the last, we added a TPU shank underfoot to help keep you more stable than ever.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/16bf8f9f-5b68-4078-93de-c81b38ef0fe0/JORDAN+TATUM+4.png', 'https://www.nike.com/t/tatum-4-basketball-shoes-EUS9ti3Y/HQ4614-601', 84.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'Collegium x Everlane Court Sneaker | Capri | Men''s', 'Rooted in the look of classic trainers, the Pillar Court III brings Collegium’s modern design language to a streamlined everyday sneaker.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2026-09-16_U-FTWR-CGM-SNKR-CRT-BLU_flat_db67e625-8453-41a2-bd34-97ae5004e350.jpg?v=1789681917', 'https://www.everlane.com/products/mens-ftwr-cgm-snkr-crt-blu', 265, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Zoom Vomero 5 Men''s Shoes', 'DURABLE CUSHIONING IN A STREET-READY PACKAGE. The Nike Zoom Vomero 5 SE SP wraps your foot in breathable support. A combination of durable synthetic leather and breathable mesh stands ready for the rigors of your day.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/494c8ea3-b469-4cad-9721-fb9146dd2119/NIKE+ZOOM+VOMERO+5.png', 'https://www.nike.com/t/zoom-vomero-5-mens-shoes-MgsTqZ/IQ9392-476', 170, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Kobe Air Force 1 Low', 'Holding on to icon status for more than 40 years, the AF1 is as reliably cool as it always has been. Durable construction, Air cushioning and grippy tread not only look great, they''ll get you through recess and everything after in style.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/a07c8c03-86dd-4813-aec3-898bcc3c3761/KOBE+AIR+FORCE+1+LOW.png', 'https://www.nike.com/t/kobe-air-force-1-low-mens-shoes-ZjtWaNqY/IB0018-103', 125, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'KD19 Basketball Shoes', 'KD is still chasing excellence. The perfect bump. The nirvanic moment where he encounters true hoop peace. The KD19 helps the kingpin in his eternal pursuit.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/dbc4781a-8408-43e2-8813-07a307f481bd/KD19.png', 'https://www.nike.com/t/kd19-basketball-shoes-zqaHv2aX/IH1117-700', 155, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Court Vision SE Men''s Shoes', 'In love with the old-school style of ''80s basketball? Meet the Court Vision. It combines synthetic leather with a rubber cupsole, bringing you all-day comfort inspired by some of the most iconic silhouettes of the past.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/15909033-8bf6-43b4-877d-cd9c725ccd63/NIKE+COURT+VISION+SE.png', 'https://www.nike.com/t/court-vision-se-mens-shoes-FpEqIQ3A/IV5722-900', 76.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Calm 2.0 Men''s Slides', 'Keep Calm and slide on. Our second version is made with softer foam while keeping all the support you need. The minimal design makes these slides easy to style with or without socks.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/540232d9-c4d9-464c-9877-05eb4d48fec8/NIKE+CALM+SLIDE+2.0.png', 'https://www.nike.com/t/calm-2-mens-slides-IC47u696/IB0183-001', 55, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Flex Control 4 Men''s Workout Shoes', 'FLEXIBILITY MEETS DURABLE STABILITY. Emphasizing lightweight comfort and stability, the Nike Flex Control 4 is tailored to explosive workouts.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/637961f9-7682-4c9a-80fe-9c72c6f73cb2/NIKE+FLEX+CONTROL+TR4.png', 'https://www.nike.com/t/flex-control-4-mens-workout-shoes-14Z62l/CD0197-002', 59.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike V5 RNR Suede Men''s Shoes', 'Tackle the everyday in a shoe that matches comfort with style. Staying true to its Y2K roots, the V5 RNR has a foam midsole that''s chunky yet lightweight. Plus, metallic details and a 3D Swoosh logo elevate this retro runner.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/049da49c-0902-40f8-b691-598518d3a074/NIKE+V5+RNR+SUEDE+2.png', 'https://www.nike.com/t/v5-rnr-suede-mens-shoes-WHxi2GRN/IX0702-400', 95, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike ReactX Rejuven8 Men''s Shoes', 'Give your feet a rest. Made with soft and responsive ReactX foam, the Rejuven8 uses some of our best tech to create a comfortable shoe you''ll want to slip on every day.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/d59c58b0-3a52-4386-8428-fcb794d68c35/NIKE+REACTX+REJUVEN8.png', 'https://www.nike.com/t/reactx-rejuven8-mens-shoes-d9QTC07e/HV5060-702', 60.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Air Liquid Max AW', 'Designed to break boundaries—classic Nike. The Air Liquid Max is made with a drop-in Cushlon Midsole stacked on top of the point-loaded Air system, making it one of the most comfortable and groundbreaking shoes we''ve ever made.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/0c1eb20e-355b-4120-bb2f-a006d8e8ae48/NIKE+AIR+LIQUID+MAX+AW.png', 'https://www.nike.com/t/air-liquid-max-aw-mens-shoes-7jzaqGDl/IV6097-300', 220, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Cortez Textile Men''s Shoes', 'You spoke. We listened. Based on your feedback, we''ve revamped the original Cortez while still keeping the retro appeal you know and love.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/7d93a817-f6c4-4df1-b596-f0498c3d24e8/NIKE+CORTEZ+TXT.png', 'https://www.nike.com/t/cortez-textile-mens-shoes-Tlm9kW/HF0263-400', 95, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Jordan Trunner O/S Men''s Shoes', 'When you wanna look as comfortable as you feel, it''s gotta be the Trunner O/S. This modern take on the original Jordan Trunner features breathable mesh and suede that keeps the upper flexible, while responsive foam underfoot gives you a', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/b0c77fa2-7a06-4008-8567-84fe17825135/JORDAN+TRUNNER+O%2FS.png', 'https://www.nike.com/t/jordan-trunner-o-s-mens-shoes-tC5xlGTw/IB3722-011', 115, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'Collegium x Everlane Summit Boot | Navy Suede | Men''s', 'Handmade in Italy from genuine Italian leather, this style is finished with a durable Vibram outsole and made with the kind of attention to detail you’ll notice with every wear.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2026-09-16_U-FTWR-CGM-SUM-BOOT-NVY_flat_aab8b59a-040a-41ee-9549-3659a802aa62.jpg?v=1789685994', 'https://www.everlane.com/products/mens-ftwr-cgm-sum-boot-nvy', 379, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 1 Low SE', 'Inspired by the original that debuted in 1985, the Air Jordan 1 Low offers a clean, classic look that''s familiar yet always fresh.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/767f5731-defd-414f-9c38-b6305ee2e525/WMNS+AIR+JORDAN+1+LOW+SE.png', 'https://www.nike.com/t/air-jordan-1-low-se-womens-shoes-jxMXgH/IX3521-010', 140, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike P-6000 Men''s Shoes', 'FROM 2006 TO 6002--ALWAYS FUTURE FORWARD. Look to the future with the Nike P-6000. Refreshing the 2006 Air Pegasus with space-age details, like chrome synthetic leather and metallic fabric, this shoe is ready for whatever''s next.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/844f8cdf-a128-43f5-b9ed-dd383878f8a4/NIKE+P-6000.png', 'https://www.nike.com/t/p-6000-mens-shoes-nX3hJMZg/IV6029-030', 115, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
