  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 5 Retro "Sunset"', 'Find the Air Jordan 5 Retro "Sunset" Women''s Shoes at Nike.com. Free delivery and returns.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/66ff0ad1-6e3f-4fff-940c-dc0237750a0c/WMNS+AIR+JORDAN+5+RETRO.png', 'https://www.nike.com/t/air-jordan-5-retro-sunset-womens-shoes-bVSXSMsI/IV5678-102', 205, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Cortez Leather Men''s Shoes', 'You spoke. We listened. Based on your feedback, we''ve revamped the original Cortez while maintaining the retro appeal you know and love.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/464ab3ac-0dc0-4fd0-84bd-eae123a2db18/NIKE+CORTEZ.png', 'https://www.nike.com/t/cortez-leather-mens-shoes-SxhPXX/DM4044-108', 76.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Court Sneaker | White / Grass Green / Parchment', 'This versatile leather sneaker is the lowest impact of its kind, which means it uses less waste, less energy, and less virgin plastic.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/6b997b61_1635.jpg?v=1753411646', 'https://www.everlane.com/products/mens-court-sneaker-white-green-parchment', 59, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Caitlin 1 "Warning Code" Basketball Shoes', 'Change the game in the Caitlin 1. Her step-back creates space on demand. Her first step sets the pace. A responsive Air Zoom Turbo unit paired with Cushlon foam helps you stay smooth and controlled through every move.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/9d1df388-ed87-4c87-a5bc-9c0717bbb6cd/CAITLIN+1.png', 'https://www.nike.com/t/caitlin-1-warning-code-basketball-shoes-cnfaZ9oZ/IH7423-700', 140, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Free Metcon 7 AMP', 'Flex your performance in the Free Metcon 7. Our most versatile training shoe gets updated with enhanced midfoot containment while still keeping our famed Nike Free technology.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/b2c4690c-2fe3-4be6-bc6f-eb0cfb9dfe3c/NIKE+FREE+METCON+7+AMP.png', 'https://www.nike.com/t/free-metcon-7-amp-mens-training-shoes-poKbzber/IR0278-001', 79.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Zoom Huarache 2K4 "Penny Hardaway"', 'It''s 2004, and Penny Hardaway takes the courts under the bright lights in NYC in custom Huaraches complete with his 1 Cent logo. Today, that court and its fans still deliver unmatched energy every game.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/da89cb58-2347-45c2-8a33-7a48b35b3a76/AIR+ZOOM+HUARACHE+2K4+PH.png', 'https://www.nike.com/t/air-zoom-huarache-2k4-penny-hardaway-mens-shoes-n99bX6f8/IV0345-001', 200, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Tread-Bare Sneaker | Forest Green', 'This piece features a round toe, laces, recycled cotton canvas upper and recycled rubber outsole.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/474eb10b_8aa4.jpg?v=1757792545', 'https://www.everlane.com/products/mens-tread-bare-sneaker2-canvas-forest-green', 104, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Luka 5 Basketball Shoes', 'On the court? Luka is a Bad man. And the shoes? Now those are nice. For the player who turns pressure into performance, the Luka 5 is designed for 360 degrees of court control.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/7c13d62f-b0ed-4407-b9a3-9db20032a873/JORDAN+LUKA+5+FAM.png', 'https://www.nike.com/t/luka-5-basketball-shoes-qbPYX73D/IW9035-500', 101.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 1 Mid', 'HERITAGE STYLE, PREMIUM COMFORT ON AND OFF THE COURT. The Air Jordan 1 Mid brings full-court style and premium comfort to an iconic look. Its Air-Sole unit cushions play on the hardwood, while the padded collar gives you a supportive feel.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/02d24606-98ee-4708-a1b8-7b85d3f26650/WMNS+AIR+JORDAN+1+MID.png', 'https://www.nike.com/t/air-jordan-1-mid-womens-shoes-TB9sVQ/BQ6472-402', 91.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Book 2 "Iron Fist" Basketball Shoes', 'Nothing beats Book’s love of classic cars — or Americana. With graphics inspired by his love for the classics, this Book 2 collaboration with Chevy epitomizes dependability, with nods to Devin’s fleet of iconic Impalas.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/b8af0aa4-9c4a-4401-8f59-c9589b666209/BOOK+2.png', 'https://www.nike.com/t/book-2-iron-fist-basketball-shoes-bSDIOe8x/FZ7013-002', 145, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Air Max 2017 Men''s Shoes', 'MAX CUSHION FOR MAX COMFORT. The Nike Air Max 2017 delivers the plush sensation you love with a full-length Max Air unit.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/ldwcyqv55jpvm7vz01cd/NIKE+AIR+MAX+2017.png', 'https://www.nike.com/t/air-max-2017-mens-shoes-BVqnkV/849559-601', 114.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Ava Rover Shoes', 'Performance-ready innovation, engineered for the city. The Nike Ava Rover elevates your everyday with a stacked ReactX midsole and an ultralight outsole designed with the streets in mind.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/fba6372b-5605-4d53-a9de-81228d73f1bd/NIKE+AVA+ROVER.png', 'https://www.nike.com/t/ava-rover-shoes-Ow09rOwc/DX4215-016', 145, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 12 Retro "Idols Become Rivals"', 'Sometimes the game is in your blood. It pairs the signature black and Varsity Red colorway in premium leather and textiles, the sunrise-inspired stitch lines on the upper hook back to the original. This is buzzer-beater style, perfected.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/b90051b9-b06d-466a-99dc-4836c72658e7/AIR+JORDAN+12+RETRO.png', 'https://www.nike.com/t/air-jordan-12-retro-idols-become-rivals-mens-shoes-pz28oX9z/CT8013-103', 215, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 1 Retro High OG "Love Letter"', 'When MJ retired from basketball, his final love letter to the game closed with the words, \', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/a2a79610-4d1f-4f78-9bf2-290ec8e6a58d/AIR+JORDAN+1+RETRO+HIGH+OG.png', 'https://www.nike.com/t/air-jordan-1-retro-high-og-love-letter-mens-shoes-KVpEM9a8/DZ5485-201', 185, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Zoom Skylon 11 Shoes', 'The Skylon 11 is back with a bang. This aerodynamic tech runner made its debut in the late 2000s and quickly made a (highly cushioned) impact.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/7792b94b-52e7-42bf-950d-36a4c220d458/NIKE+ZOOM+SKYLON+11.png', 'https://www.nike.com/t/zoom-skylon-11-shoes-9SAvKtxl/IU1869-700', 135, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Kobe 10 Protro Basketball Shoes', 'Sculpted out of endless curiosity, the Kobe 10 Protro continues an obsession with better. Originally released in 2015, this silhouette has been remastered from the inside out for today’s game.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/e8f30e87-06e7-408a-8107-5de9de3ed45f/KOBE+X+PROTRO.png', 'https://www.nike.com/t/kobe-10-protro-basketball-shoes-3a6IgbGI/IO3415-100', 190, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 3 Retro "Laser"', 'Clean and supreme, the AJ3 returns with all of its classic style and grace. Premium leather in the upper and luxurious suede overlays combine with visible Air in the sole to make a comfortable, everyday icon.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/cb5b6d74-174f-45bd-b433-1b53c0f72e11/AIR+JORDAN+3+RETRO+LASER.png', 'https://www.nike.com/t/air-jordan-3-retro-laser-mens-shoes-NjtYwkEm/JA1369-001', 230, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Precision 7 Men''s Basketball Shoes', 'Score at will at the rim or from deep in the Nike Precision 7. Crafted with a combination of ground control, comfort and on-court traction, it''s perfect for instant impact plays when your name is called for the next pickup game.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/8c2e57b1-aa47-434a-a3f1-f2bf4a8090de/NIKE+PRECISION+VII.png', 'https://www.nike.com/t/precision-7-mens-basketball-shoes-IKdj8qoO/FN4322-001', 57.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Kobe III Low Protro', 'Elevate your game. Lightweight and breathable, the Kobe III pairs airy knits with durable synthetic leather for on-court comfort. Nike Air cushioning and sticky traction give you cushioning and grip.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/1c9fd0b5-1dde-4be3-a267-6a38c9b55ed8/KOBE+III+LOW+PROTRO.png', 'https://www.nike.com/t/kobe-iii-low-protro-mens-basketball-shoes-QPSxAdxo/IV7127-001', 190, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 4 Retro "Tour Yellow"', 'All the iconic details of the AJ4 are here, including the attention-grabbing eyestays and mesh windows of the original. What''s your little one get? Jordan style made just for little feet.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/a01447f6-0ff6-4dac-9566-e1a41d37cbf3/AIR+JORDAN+4+RETRO.png', 'https://www.nike.com/t/air-jordan-4-retro-tour-yellow-mens-shoes-XcyMqswH/IO2463-102', 220, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike SB Dunk Low Pro Skate Shoes', 'You can always count on a classic. The Dunk Low pairs iconic color blocking with premium materials and plush padding for game-changing comfort that lasts. The possibilities are endless—how will you wear your Dunks?', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/10ab3573-9d5f-4535-bc11-aaa807b4ac36/NIKE+SB+DUNK+LOW+PRO+QS.png', 'https://www.nike.com/t/sb-dunk-low-pro-skate-shoes-pRtiDSyV/IO9508-200', 75.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Air Max "Joga Bonito"', 'Find the Nike Air Max "Joga Bonito" Men''s Shoes at Nike.com. Free delivery and returns.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/beeaaf48-50e5-4493-af17-1f005600e82a/NIKE+AIR+MAX+JOGA+BONITO.png', 'https://www.nike.com/t/air-max-joga-bonito-mens-shoes-GEpH4lmj/IO1753-003', 180, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Air Force 1 ''07', 'Comfortable, durable and timeless—it’s number one for a reason. The classic ‘80s construction pairs smooth leather with bold details for style that tracks whether you’re on court or on the go.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/e6da41fa-1be4-4ce5-b89c-22be4f1f02d4/AIR+FORCE+1+%2707.png', 'https://www.nike.com/t/air-force-1-07-mens-shoes-DZejrQoC/CW2288-111', 115, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'Collegium x Everlane Summit Boot | Desert Taupe | Men''s', 'Handmade in Italy from genuine Italian leather, this style is finished with a durable Vibram outsole and made with the kind of attention to detail you’ll notice with every wear.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2026-09-16_U-FTWR-CGM-SUM-BOOT-TAUPE_flat_9e847fed-4c72-4d84-befb-a9bfb2a82d11.jpg?v=1789686168', 'https://www.everlane.com/products/mens-ftwr-cgm-sum-boot-taupe', 379, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 4 RM', 'These sneakers reimagine the instantly recognizable AJ4 for life on the go. We centered comfort and durability while keeping the heritage look you love.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/f519399f-82d0-44e0-9691-ec546318b486/AIR+JORDAN+4+RM.png', 'https://www.nike.com/t/air-jordan-4-rm-mens-shoes-Q1Cbd2ry/FQ7939-009', 108.97, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Ja 3 Basketball Shoes', 'Every time Ja steps on the court, it''s showtime. To help him elevate his game, we worked with him to make the bounciest Ja signature shoe so far. The Ja 3 is light, tough and a game-changer with full-length Hybrid ZoomX foam.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/2c2daf43-8ce1-46c3-be3c-8d2f644c0edb/JA+3.png', 'https://www.nike.com/t/ja-3-basketball-shoes-G1nmGiZE/IV4426-102', 125, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'Collegium x Everlane Pista Sneaker | Crimson | Men''s', 'The Pillar Pista takes Collegium’s low-top driving shoe silhouette and gives it a refined Italian finish.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2026-09-16_U-FTWR-CGM-SNKR-PSTA-RED_flat_f18f6abd-98ba-485f-9504-e503367e33bf.jpg?v=1789682918', 'https://www.everlane.com/products/mens-ftwr-cgm-snkr-psta-red', 240, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Air Jordan 8 Retro "Chrome"', 'MJ''s 8th signature shoe first debuted during the ''92-''93 championship season, but the \', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_126ab356-44d8-4a06-89b4-fcdcc8df0245,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/12304076-43a9-40e3-b65c-7b15e324e1bd/AIR+JORDAN+8+RETRO.png', 'https://www.nike.com/t/air-jordan-8-retro-chrome-mens-shoes-w8gbGIiw/305381-007', 215, 'USD', 'Shoes', 'Male', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Bow Sandal | Deep Amber Satin', 'A polished leather outsole keeps things refined, while the ultra-slim profile gives that simple, understated look. Perfect for when you want to dress up summer outfits—without overthinking it.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/e29fc79f_b247.jpg?v=1753411937', 'https://www.everlane.com/products/womens-leather-bow-sandal-deep-amber', 63, 'USD', 'Shoes', 'Female', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Day Twist Heel | Black', 'Our buttery soft nappa leather has taken on a new form. The Day Twist Heel features our handcrafted leather with a knot-twist detail and flared block heel for all-day wearability.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/c8ed8d9d_e031.jpg?v=1753411639', 'https://www.everlane.com/products/womens-leather-day-twist-heel-black-tan', 50, 'USD', 'Shoes', 'Female', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Leather Flip Flop | Black', 'This thong sandal features unique stitch detailing and a leather-wrapped toe post for all-day comfort. The bovine leather footbed lining and bio-based EVA foam cushioning make every step feel like a breeze.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/479aa12b_0209.jpg?v=1777939205', 'https://www.everlane.com/products/womens-leather-flip-flop-black', 90, 'USD', 'Shoes', 'Female', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Day Boot in ReKnit | Black', 'This piece features a pull-on, mid-shaft sock bootie, with a flared block heel, 2.15" heel height, and 5.75"shaft height, made of our breathable ReKnit fabric.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/344b3a73_35e3.jpg?v=1753411712', 'https://www.everlane.com/products/women-reknit-day-boot-black', 53, 'USD', 'Shoes', 'Female', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'The Outlaw Mule | Saddle Brown', 'This piece features a slip-on, tapered toe mule, block, leather stacked heel with leather upper and lining, leather outsole and welt.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/2bcc40cc_e905.jpg?v=1753411736', 'https://www.everlane.com/products/womens-outlaw-mule-saddle-brown', 50, 'USD', 'Shoes', 'Female', '{}', '{}', true, 'verified', now(), NULL),
  ((SELECT id FROM public.brands WHERE name = 'Everlane'), 'Studio Kitten Heel Bootie | Russet', 'Designed with a two-inch heel height and foam insole, there’s no need to sacrifice comfort over style in this 100% leather bootie.', 'https://cdn.shopify.com/s/files/1/0623/7916/3734/files/28ec2fcd_8cef.jpg?v=1775782811', 'https://www.everlane.com/products/womens-studio-kitten-heel-bootie-russet-suede', 89, 'USD', 'Shoes', 'Female', '{}', '{}', true, 'verified', now(), NULL),
