  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Dunk Low Women''s Shoes', 'The ''80s basketball icon returns with classic details and throwback hoops flair. Channeling vintage style back onto the streets, the multiple metallic silver Swoosh logo dubraes let you accessorize for a modern look while its crisp leather', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/ec7ffb56-1a15-40c2-a00a-bfd2476439d7/WMNS+NIKE+DUNK+LOW.png', 'https://www.nike.com/t/dunk-low-womens-shoes-ppQwKZ/FV1311-100', 120, 'USD', 'Shoes', 'Female', '{}', '{}', true, 'verified', now(), NULL),
