  ((SELECT id FROM public.brands WHERE name = 'Nike'), 'Nike Pegasus Plus 2 Women''s Road Running Shoes', 'Exposed Air Zoom unit meets an ultralight design for next-level responsiveness. Take responsive cushioning to the next level with the Pegasus Plus 2.', 'https://static.nike.com/a/images/t_web_pw_592_v2/f_auto/u_9ddf04c7-2a9a-4d76-add1-d15af8f0263d,c_scale,fl_relative,w_1.0,h_1.0,fl_layer_apply/d01528ce-7baf-4e7a-aa8e-87c45085f8c8/W+NIKE+PEGASUS+PLUS+2.png', 'https://www.nike.com/t/pegasus-plus-2-womens-road-running-shoes-IApQlsjO/IM2543-600', 170, 'USD', 'Shoes', 'Female', '{}', '{}', true, 'verified', now(), NULL),
